"use strict";App.Pages.CaldavSettings=function(){function deserialize(caldavSettings){caldavSettings.forEach(function(caldavSetting){$("[data-field=\""+caldavSetting.name+"\"]").val(caldavSetting.value)})}function serialize(){var caldavSettings=[];return $("#caldav-settings [data-field]").each(function(index,field){var $field=$(field);caldavSettings.push({name:$field.data("field"),value:$field.val()})}),caldavSettings}function onSaveSettingsClick(){App.Http.CaldavSettings.save(serialize()).done(function(){App.Layouts.Backend.displayNotification(lang("settings_saved"))})}var $saveSettings=$("#save-settings");return document.addEventListener("DOMContentLoaded",function(){$saveSettings.on("click",onSaveSettingsClick),deserialize(vars("caldav_settings"))}),{}}();